import{_ as o,c as t,o as a,ae as s}from"./chunks/framework.DYBsrYGD.js";const g=JSON.parse('{"title":"Vue 2 与 Vue 3 综合差异速查","description":"","frontmatter":{},"headers":[],"relativePath":"框架和类库/Vue2与Vue3对比/综合差异速查.md","filePath":"框架和类库/Vue2与Vue3对比/综合差异速查.md"}'),i={name:"框架和类库/Vue2与Vue3对比/综合差异速查.md"};function r(n,e,d,l,c,u){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="vue-2-与-vue-3-综合差异速查" tabindex="-1">Vue 2 与 Vue 3 综合差异速查 <a class="header-anchor" href="#vue-2-与-vue-3-综合差异速查" aria-label="Permalink to &quot;Vue 2 与 Vue 3 综合差异速查&quot;">​</a></h1><blockquote><p>响应式专篇见：<a href="./响应式对比.html">响应式对比</a></p></blockquote><h2 id="生命周期对照-选项式" tabindex="-1">生命周期对照（选项式） <a class="header-anchor" href="#生命周期对照-选项式" aria-label="Permalink to &quot;生命周期对照（选项式）&quot;">​</a></h2><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Vue 2 选项式  →  Vue 3 选项式 / 组合式（常见对应）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">beforeCreate  →  使用 </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()（组合式，无等价 beforeCreate）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">created       →  使用 </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">beforeMount   →  onBeforeMount</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mounted       →  onMounted</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">beforeUpdate  →  onBeforeUpdate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">updated       →  onUpdated</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">beforeDestroy →  onBeforeUnmount</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">destroyed     →  onUnmounted</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errorCaptured →  onErrorCaptured</span></span></code></pre></div><p><strong>说明</strong>：组合式里没有 <code>beforeCreate</code> / <code>created</code>，逻辑直接写在 <code>setup</code> 顶层（或 <code>&lt;script setup&gt;</code> 顶层）即可。</p><p>与 <code>keep-alive</code> 相关的 <code>activated</code> / <code>deactivated</code> 在两版中名称一致。</p><h2 id="核心差异清单" tabindex="-1">核心差异清单 <a class="header-anchor" href="#核心差异清单" aria-label="Permalink to &quot;核心差异清单&quot;">​</a></h2><h3 id="_1-卸载阶段命名" tabindex="-1">1. 卸载阶段命名 <a class="header-anchor" href="#_1-卸载阶段命名" aria-label="Permalink to &quot;1. 卸载阶段命名&quot;">​</a></h3><ul><li>Vue 2：<code>beforeDestroy</code>、<code>destroyed</code></li><li>Vue 3：<code>beforeUnmount</code>、<code>unmounted</code></li></ul><h3 id="_2-组件通信与实例-api" tabindex="-1">2. 组件通信与实例 API <a class="header-anchor" href="#_2-组件通信与实例-api" aria-label="Permalink to &quot;2. 组件通信与实例 API&quot;">​</a></h3><ul><li>Vue 3 移除 <strong><code>$on</code> / <code>$off</code> / <code>$once</code></strong>，默认不再自带全局事件总线；可用 <strong><code>mitt</code></strong> 等库。</li><li>Vue 3 移除 <strong><code>v-bind:xxx.sync</code></strong>，父子双向多用 <strong><code>v-model</code></strong>（或多组 <code>v-model:xxx</code>）。</li><li><strong><code>v-model</code> 在组件上</strong><ul><li>Vue 2：常见为 <strong><code>value</code> + <code>input</code></strong>（或依实现而定）。</li><li>Vue 3：默认 <strong><code>modelValue</code> + <code>update:modelValue</code></strong>，可用 <strong><code>v-model:propName</code></strong> 自定义。</li></ul></li><li>Vue 3 移除 <strong><code>$listeners</code></strong>，相关行为并入 <strong><code>$attrs</code></strong>。</li><li>Vue 3 移除 <strong><code>$children</code></strong>，访问子实例宜用 <strong><code>ref</code></strong>。</li></ul><h3 id="_3-模板指令" tabindex="-1">3. 模板指令 <a class="header-anchor" href="#_3-模板指令" aria-label="Permalink to &quot;3. 模板指令&quot;">​</a></h3><ul><li><strong><code>v-for</code> 与 <code>v-if</code> 同节点时的优先级</strong><ul><li>Vue 2：<code>v-for</code> 更高。</li><li>Vue 3：<code>v-if</code> 更高（不建议同节点混用，可读性差）。</li></ul></li><li>Vue 3 新增 <strong><code>v-memo</code></strong>（缓存部分 DOM）。</li><li>Vue 3 移除 <strong><code>.sync</code></strong>（见上）。</li></ul><h3 id="_4-开发范式" tabindex="-1">4. 开发范式 <a class="header-anchor" href="#_4-开发范式" aria-label="Permalink to &quot;4. 开发范式&quot;">​</a></h3><ul><li>Vue 2：以<strong>选项式 API</strong>为主。</li><li>Vue 3：选项式仍可用，并增加<strong>组合式 API</strong>（<code>setup</code> / <code>&lt;script setup&gt;</code>、<code>ref</code>、<code>reactive</code>、<code>watch</code>、<code>computed</code>、以 <code>on</code> 开头的生命周期等）。</li></ul><h3 id="_5-响应式实现" tabindex="-1">5. 响应式实现 <a class="header-anchor" href="#_5-响应式实现" aria-label="Permalink to &quot;5. 响应式实现&quot;">​</a></h3><p>见 <a href="./响应式对比.html">响应式对比</a>。</p><h2 id="通信与全局-api-差异-补充" tabindex="-1">通信与全局 API 差异（补充） <a class="header-anchor" href="#通信与全局-api-差异-补充" aria-label="Permalink to &quot;通信与全局 API 差异（补充）&quot;">​</a></h2><p>以下在「概览类笔记」里常与通用通信写在一起，此处单独汇总为<strong>版本差异</strong>：</p><ul><li><strong>组件上的事件</strong><ul><li>Vue 2：组件上监听默认多为<strong>自定义事件</strong>；监听原生 DOM 常需 <strong><code>.native</code></strong>。</li><li>Vue 3：满足条件时可为 <strong>DOM 事件</strong>（事件名须为 DOM 事件名、子组件有根、且未用 <code>defineEmits</code> 声明同名事件等）；否则为自定义事件。</li></ul></li><li><strong>全局事件总线</strong><ul><li>Vue 2：常用 <code>$bus</code> 等自建总线。</li><li>Vue 3：无内置 <code>$on/$off</code>，多用 <strong><code>mitt</code></strong> 等。</li></ul></li><li><strong><code>$attrs</code> / <code>$listeners</code></strong><ul><li>Vue 2：<code>$listeners</code> 单独存在。</li><li>Vue 3：无 <code>$listeners</code>，并入 <strong><code>$attrs</code></strong>。</li></ul></li><li><strong><code>$parent</code> / <code>$children</code> / <code>$refs</code></strong><ul><li>Vue 3 无 <strong><code>$children</code></strong>，请用 <strong><code>ref</code></strong> 获取子组件实例。</li></ul></li></ul><p>状态管理习惯上：Vue 2 项目常见 <strong>Vuex</strong>，Vue 3 新项目常见 <strong>Pinia</strong>（二者也均可跨版本使用，以项目为准）。</p><h2 id="虚拟-dom-与更新策略-对照" tabindex="-1">虚拟 DOM 与更新策略（对照） <a class="header-anchor" href="#虚拟-dom-与更新策略-对照" aria-label="Permalink to &quot;虚拟 DOM 与更新策略（对照）&quot;">​</a></h2><h3 id="性能与编译" tabindex="-1">性能与编译 <a class="header-anchor" href="#性能与编译" aria-label="Permalink to &quot;性能与编译&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方面</th><th>Vue 3</th><th>Vue 2</th></tr></thead><tbody><tr><td>模板</td><td>编译期优化更多，减少运行时解析成本</td><td>更多依赖运行时解析</td></tr><tr><td>VNode</td><td>更轻量</td><td>相对更重</td></tr><tr><td>更新</td><td>Patch 更细粒度，减少无效更新</td><td>相对粗放</td></tr><tr><td>包体积</td><td>更易 <strong>Tree-Shaking</strong> 去掉未用 API</td><td>整体打包形态相对固定</td></tr></tbody></table><h3 id="api-形态对-vdom-的影响" tabindex="-1">API 形态对 VDOM 的影响 <a class="header-anchor" href="#api-形态对-vdom-的影响" aria-label="Permalink to &quot;API 形态对 VDOM 的影响&quot;">​</a></h3><ul><li>Vue 3 的<strong>组合式 API</strong>更利于逻辑复用与组织，间接影响渲染与更新路径的设计。</li><li>Vue 2 以<strong>选项式</strong>为主，复杂场景下逻辑易分散在多个选项中。</li></ul><h3 id="与响应式的关系" tabindex="-1">与响应式的关系 <a class="header-anchor" href="#与响应式的关系" aria-label="Permalink to &quot;与响应式的关系&quot;">​</a></h3><ul><li>Vue 3：<strong>Proxy</strong> 响应式 + 更细的更新路径，常带来更可控的更新。</li><li>Vue 2：<strong>Object.defineProperty</strong>，对新增属性等场景需额外 API 配合。</li></ul><h3 id="vue-3-在-diff-更新路径上的常见表述-补充" tabindex="-1">Vue 3 在 Diff / 更新路径上的常见表述（补充） <a class="header-anchor" href="#vue-3-在-diff-更新路径上的常见表述-补充" aria-label="Permalink to &quot;Vue 3 在 Diff / 更新路径上的常见表述（补充）&quot;">​</a></h3><ul><li>更偏<strong>增量</strong>的更新策略，减少无效 DOM 操作。</li><li><strong>静态提升</strong>等编译优化：尽量让不变节点少参与 Diff。</li><li>对动态节点与 <code>key</code> 的追踪更细，便于局部<strong>最小化</strong>更新。</li><li>事件侦听等运行时代码路径相对 Vue 2 往往更省（以实际版本为准）。</li></ul><h2 id="nexttick-差异-原理层面" tabindex="-1">nextTick 差异（原理层面） <a class="header-anchor" href="#nexttick-差异-原理层面" aria-label="Permalink to &quot;nextTick 差异（原理层面）&quot;">​</a></h2><h3 id="vue-2" tabindex="-1">Vue 2 <a class="header-anchor" href="#vue-2" aria-label="Permalink to &quot;Vue 2&quot;">​</a></h3><p>为兼容旧浏览器，将回调放入异步队列时，会按能力依次尝试 <strong>Promise → MutationObserver → setImmediate → setTimeout</strong> 等方案。</p><h3 id="vue-3" tabindex="-1">Vue 3 <a class="header-anchor" href="#vue-3" aria-label="Permalink to &quot;Vue 3&quot;">​</a></h3><p>不再面向过旧浏览器时，可主要依赖 <strong>Promise</strong> 等现代方案；<strong>不传回调</strong>时，<code>nextTick()</code> 会返回 <strong>Promise</strong>，便于 <code>await</code>。</p><p><strong>记忆点</strong>：Vue 2 的「多种 <code>timerFunc</code>」主要来自<strong>兼容</strong>；Vue 3 可更<strong>简单、一致</strong>。</p>`,36)])])}const p=o(i,[["render",r]]);export{g as __pageData,p as default};
